package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ReferenceType_getGenericSignature_TriageGen0Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        Class<?> clazz = String.class;
        JavaType mockedReferencedType = mock(JavaType.class);

        // We need to use the static factory method to create the instance 
        // because the constructor is protected.
        ReferenceType referenceType = ReferenceType.construct(clazz, mockedReferencedType, null, null);

        StringBuilder sb = new StringBuilder("Prefix:");

        // Mock the behavior of the referenced type's getGenericSignature
        // The method appends to the existing SB and returns it.
        when(mockedReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("MockedType");
            return passedSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected flow:
        // 1. _classSignature is called (internally appends class name)
        // 2. sb.append('<')
        // 3. _referencedType.getGenericSignature(sb) -> appends "MockedType"
        // 4. sb.append(';')

        // Note: _classSignature behavior depends on internal implementation of ReferenceType, 
        // but typically it appends the class name. 
        // Since we cannot easily mock the private/protected _classSignature call in a pure unit test 
        // without PowerMock, we validate the structure and the interaction with the mocked dependency.

        String expectedEnd = "<MockedType;";
        String resultString = result.toString();

        // Verify the structure: must end with < + content + ;
        // Since we don't know the exact output of _classSignature (which appends to sb), 
        // we check if the suffix is correct.
        assert(resultString.endsWith(expectedEnd));

        // Verify interaction with the dependency
        verify(mockedReferencedType).getGenericSignature(any(StringBuilder.class));
    }

    @Test
    public void testGetGenericSignature_EmptyBuilder() {
        // Arrange
        Class<?> clazz = Integer.class;
        JavaType mockedReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(clazz, mockedReferencedType, null, null);

        StringBuilder sb = new StringBuilder();

        when(mockedReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("IntType");
            return passedSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Result should contain <IntType;
        String resultString = result.toString();
        assert(resultString.contains("<IntType;"));
    }
}
